javas.java:

int def demandDuringLeadTime(int:avgDailySales, int:leadTimeDays) {
    return avgDailySales * leadTimeDays;
}


int def safetyStockLevel(int:safetyStock, int:avgDailySales, double:supplierReliability, boolean:promotion) {
    int level = safetyStock;
    if (promotion) {
        level = level + avgDailySales * 5;
    }
    if (supplierReliability < 0.9) {
        level = level + avgDailySales * 3;
    }
    return level;
}


int def targetStock(int:safetyStock, int:demandDuringLeadTime, str:seasonFactor, int:avgDailySales) {
    int target = safetyStock + demandDuringLeadTime;
    if (seasonFactor == "PEAK") {
        target = target + avgDailySales * 7;
    } else if (seasonFactor == "OFF") {
        target = target - avgDailySales * 3;
    }
    if (target < 0) {
        target = 0;
    }
    return target;
}


int def shortage(int:targetStock, int:currentStock) {
    int gap = targetStock - currentStock;
    if (gap < 0) {
        gap = 0;
    }
    return gap;
}


int def adjustToMoq(int:qty, int:moq) {
    int result = qty;
    if (qty > 0 && qty < moq) {
        result = moq;
    }
    return result;
}


int def roundToPack(int:qty, int:packSize) {
    if (qty <= 0) {
        return 0;
    }
    if (packSize <= 1) {
        return qty;
    }
    int rounded = 0;
    while (rounded < qty) {
        rounded = rounded + packSize;
    }
    return rounded;
}


int def stockDays(int:currentStock, int:avgDailySales) {
    if (avgDailySales <= 0) {
        return 999;
    }
    return currentStock / avgDailySales;
}


str def urgency(int:stockDays, int:leadTimeDays) {
    if (stockDays <= leadTimeDays) {
        return "CRITICAL";
    } else if (stockDays <= leadTimeDays + 3) {
        return "HIGH";
    } else if (stockDays <= leadTimeDays + 7) {
        return "MEDIUM";
    } else {
        return "LOW";
    }
}


boolean def suggestExpress(int:stockDays, int:leadTimeDays, str:seasonFactor) {
    if (stockDays <= leadTimeDays) {
        return true;
    } else if (seasonFactor == "PEAK" && stockDays <= leadTimeDays + 3) {
        return true;
    } else {
        return false;
    }
}


int def cappedQty(int:qty, int:maxOrder) {
    int result = qty;
    if (result > maxOrder) {
        result = maxOrder;
    }
    return result;
}
